//! 🧾️ An original typed value supplies a bounded independent metadata owner per declared recipient.
use semio_framework_value::retained_clone::RetainedClone;
use semio_framework_job::{OriginalConstructionDemand,OriginalSourceBinding,OriginalTurnFailure,StepContext,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneOwner,RetainedCloneClose}};
use std::{collections::VecDeque,mem::{ManuallyDrop,size_of}};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original typed metadata copies source changed")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
/// 🪡️ Each resulting origin owns its actual bounded text copies and preserves the complete original metadata.
pub struct OriginalValueCopies<T:RetainedClone>{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,total:usize,original:ManuallyDrop<Option<T>>,source:ManuallyDrop<Option<RetainedCloneSource<T>>>,cursor:ManuallyDrop<Option<RetainedCloneOwner<T>>>,values:ManuallyDrop<Option<VecDeque<T>>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl<T:RetainedClone> OriginalValueCopies<T>{
 pub fn admit(original:&mut Option<T>,count:usize,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if original.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};admit_original_construction(cx,output,construction(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,total:count,original:ManuallyDrop::new(original.take()),source:ManuallyDrop::new(None),cursor:ManuallyDrop::new(None),values:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}),receipt(d))))}
 fn next_phase(&mut self,phase:u8,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=fixed::<u8>();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{self.phase=phase;Ok(((),receipt(d)))})?;Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original typed metadata copies was cancelled").into())}if cx.should_yield(){return Ok(false)}match self.phase{
  0=>{let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};let grant=cx.retained_grant();admit_original_construction(cx,&mut self.source,construction(d),|_|RetainedCloneSource::admit_owned(self.original.take().unwrap(),(),grant).map_err(|(error,original,())|{*self.original=Some(original);error}))?;if self.source.is_some(){self.phase=1}},
  1=>{let d=RetirementDemand{capacity_bytes:self.total.checked_mul(size_of::<T>()).ok_or_else(invalid)?,..fixed::<VecDeque<T>>()};admit_original_construction(cx,&mut self.values,construction(d),|_|{let mut values=VecDeque::new();values.try_reserve_exact(self.total).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original typed metadata copies rows could not be reserved"))?;let mut p=receipt(d);p.retained_capacity_bytes=values.capacity()*size_of::<T>();Ok((values,p))})?;if self.values.is_some(){self.phase=2}},
  2=>{if self.values.as_ref().unwrap().len()==self.total{self.next_phase(6,cx)?;return Ok(false)}let d=fixed::<RetainedCloneOwner<T>>();admit_original_construction(cx,&mut self.cursor,construction(d),|_|Ok((RetainedCloneOwner::default(),receipt(d))))?;if self.cursor.is_some(){self.phase=3}},
  3=>{let source=self.source.as_ref().unwrap().try_borrow()?;let cursor=self.cursor.as_mut().unwrap();let d=cursor.advance_demands(source,self.body)?;let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{let step=cursor.advance(source,self.body,grant)?;if matches!(step,RetainedCloneStep::Complete(_)){self.phase=4}Ok(((),step.progress()))})?;},
  4=>{let d=fixed::<(T,usize)>();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{let value=self.cursor.as_mut().unwrap().take().ok_or_else(invalid)?;self.values.as_mut().unwrap().push_back(value);self.phase=5;Ok(((),receipt(d)))})?;},
  5=>{if self.close_cursor(cx)?{self.next_phase(2,cx)?}},
  6=>{if self.close_source(cx)?{self.next_phase(7,cx)?}},
  7=>return Ok(true),_=>unreachable!(),
 }Ok(self.phase==7)}
 fn close_cursor(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(cursor)=self.cursor.as_mut()else{return Ok(true)};if !cursor.terminal_is_empty(){let d=cursor.selected_close_demand(self.body)?;close_original_retained_step(cx,d,|grant|cursor.close_step(grant))?;return Ok(false)}let d=fixed::<Option<RetainedCloneOwner<T>>>();close_original_retained_step(cx,d,|_|{self.cursor.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(false)}
 fn close_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(source)=self.source.as_mut()else{return Ok(true)};if !source.terminal_is_empty(){let d=source.next_close_demand(self.body)?;close_original_retained_step(cx,d,|grant|source.close_step(grant))?;return Ok(false)}let d=fixed::<Option<RetainedCloneSource<T>>>();close_original_retained_step(cx,d,|_|{self.source.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(false)}
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<VecDeque<T>>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=7||self.closing||self.values.is_none(){return Err(invalid().into())}let d=fixed::<(Option<VecDeque<T>>,Option<VecDeque<T>>)>();admit_original_construction(cx,output,construction(d),|_|Ok((self.values.take().unwrap(),receipt(d))))}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.closing=true;if !self.close_cursor(cx)?||!self.close_source(cx)?{return Ok(false)}if self.original.is_some(){let d=self.retirement.next_owner_demands::<T>(true,&None,self.body)?;close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.original,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}if !self.retirement.is_empty(){let selection=self.retirement.select(self.body)?;let d=selection.demands();close_original_retained_step(cx,d,|grant|selection.step(grant))?;return Ok(false)}if self.values.is_some(){let d=self.retirement.next_owner_demands::<VecDeque<T>>(true,&None,self.body)?;close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.values,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.original.is_none()&&self.source.is_none()&&self.cursor.is_none()&&self.values.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<T:RetainedClone> Drop for OriginalValueCopies<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original typed metadata copies requires funded closure")}}

